  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('pintu-upvc', 'Pintu Ekonomis', 'Pintu Kupu UPVC Ekonomis adalah pilihan tepat untuk Anda yang membutuhkan pintu berkualitas dengan harga yang terjangkau. Terbuat dari material Unplasticized Polyvinyl Chloride (UPVC), pintu ini tetap menawarkan daya tahan tinggi, sifat tahan cuaca, serta ketahanan terhadap serangan rayap.', 'Rp. 1.600.000', '90cm x 210cm', array['/images/products/pintu-ekonomis-1.png', '/images/products/pintu-ekonomis-2.png', '/images/products/pintu-ekonomis-3.png']::text[], 0);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('pintu-upvc', 'Pintu Geser UPVC', 'Pintu geser UPVC adalah solusi untuk akses yang mudah dan ruang terbuka yang indah. Terbuat dari bahan UPVC berkualitas tinggi, pintu ini menawarkan kekuatan, ketahanan, serta kemudahan dalam perawatan. Desainnya yang modern memungkinkan bukaan yang lancar secara horizontal, mengoptimalkan ruang dan pencahayaan alami. Pintu geser UPVC juga memberikan isolasi yang baik, membantu mempertahankan suhu dalam ruangan dan mengurangi kebisingan dari luar. Ideal untuk rumah tinggal dan bangunan komersial yang mengutamakan gaya, kenyamanan, dan efisiensi energi.', 'Rp. 2.312.000', '180cm x 210cm', array['/images/products/pintu-geser-1.png', '/images/products/pintu-geser-2.png', '/images/products/pintu-geser-3.png']::text[], 1);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('pintu-upvc', 'Pintu Lipat UPVC', 'Pintu lipat UPVC adalah pilihan yang elegan dan praktis untuk meningkatkan estetika dan fungsi ruang. Terbuat dari bahan UPVC berkualitas tinggi, pintu ini dirancang untuk membuka ruang secara maksimal dengan gaya yang modern. Keunggulannya terletak pada kekuatan, tahan lama, serta kemudahan perawatan. Dengan sistem lipatan yang lancar, pintu ini mengoptimalkan penggunaan ruang dan pencahayaan alami, sesuai untuk berbagai jenis bangunan dari hunian pribadi hingga proyek komersial. Memiliki sifat isolasi yang baik untuk menjaga kenyamanan dalam ruangan dan mengurangi gangguan dari luar, menjadikannya pilihan terbaik untuk desain yang fungsional dan estetis.', 'Rp. 4.900.000', '180cm x 210cm', array['/images/products/pintu-lipat-1.png', '/images/products/pintu-lipat-2.png', '/images/products/pintu-lipat-3.png']::text[], 2);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('pintu-upvc', 'Pintu UPVC Swing', 'Pintu UPVC swing merupakan pilihan elegan dan praktis untuk pintu masuk utama atau interior. Terbuat dari bahan UPVC berkualitas tinggi, pintu ini dirancang untuk memberikan kekuatan, daya tahan, dan kemudahan perawatan. Desainnya yang swing memungkinkan bukaan pintu yang mudah dan lancar ke dalam atau keluar ruangan, menambah nilai estetika dan fungsionalitas ruang. Dengan kemampuan isolasi yang baik, pintu UPVC swing membantu mempertahankan suhu ruangan dan mengurangi kebisingan dari luar, cocok untuk rumah tinggal, apartemen, atau bangunan komersial yang mengutamakan kenyamanan dan keamanan.', 'Rp. 2.195.000', '90cm x 210cm', array['/images/products/pintu-swing-1.png', '/images/products/pintu-swing-2.png', '/images/products/pintu-swing-3.png']::text[], 3);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('pintu-upvc', 'Pintu Kupu UPVC', 'Pintu kupu UPVC adalah jenis pintu yang terbuat dari material Unplasticized Polyvinyl Chloride (UPVC), yang terkenal karena daya tahannya, perawatan yang rendah, serta sifatnya yang tahan terhadap cuaca dan serangan rayap. Jenis pintu ini sering digunakan untuk area yang membutuhkan ventilasi dan pencahayaan lebih baik, seperti pintu menuju taman, teras, atau balkon.', 'Rp. 3.300.000', '180cm x 210cm', array['/images/products/pintu-kupu-1.png', '/images/products/pintu-kupu-2.png', '/images/products/pintu-kupu-3.png']::text[], 4);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('jendela-upvc', 'Jendela Geser', 'Jendela geser UPVC merupakan produk yang terbuat dari bahan UPVC (Unplasticized Polyvinyl Chloride) yang kuat dan tahan lama. Desainnya memungkinkan jendela untuk digeser secara horizontal, memberikan kemudahan dalam penggunaan dan estetika yang modern. Jendela ini cocok digunakan untuk rumah tinggal maupun bangunan komersial karena tahan terhadap cuaca ekstrem dan membutuhkan sedikit perawatan. Dengan kualitas isolasi yang baik, jendela geser UPVC juga membantu mengurangi kebisingan dari luar dan meningkatkan efisiensi energi bangunan.', 'Rp. 2.350.000', '120cm x 120cm', array['/images/products/jendela-geser-1.png', '/images/products/jendela-geser-2.png', '/images/products/jendela-geser-3.png']::text[], 0);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('jendela-upvc', 'Jendela Jungkit UPVC', 'Jendela jungkit UPVC adalah produk inovatif yang menggunakan bahan UPVC (Unplasticized Polyvinyl Chloride) berkualitas tinggi. Desainnya memungkinkan jendela untuk dibuka dengan cara dikangkangi (jungkit) ke atas atau ke bawah, memberikan fleksibilitas dalam pengaturan ventilasi udara. Jendela ini menyediakan kombinasi antara kekuatan, keamanan, dan tampilan estetika modern. Material UPVC membuatnya tahan terhadap cuaca ekstrem dan membutuhkan sedikit perawatan. Dengan kemampuan isolasi yang baik, jendela jungkit UPVC membantu menjaga kehangatan dan mengurangi kebisingan dari luar. Cocok digunakan untuk berbagai jenis bangunan, baik hunian pribadi maupun komersial, sebagai solusi praktis dan efisien untuk meningkatkan kenyamanan ruangan.', 'Rp. 1.244.000', '60cm x 120cm', array['/images/products/jendela-jungkit-1.png', '/images/products/jendela-jungkit-2.png', '/images/products/jendela-jungkit-3.png']::text[], 1);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('jendela-upvc', 'Jendela Fixed UPVC Kaca Mati', 'Jendela fixed UPVC adalah produk jendela yang dirancang untuk tetap dalam posisi tertutup tanpa kemampuan untuk dibuka. Terbuat dari bahan UPVC (Unplasticized Polyvinyl Chloride) yang tahan lama dan kuat, jendela ini menawarkan keamanan yang baik serta tahan terhadap cuaca ekstrem. Desainnya memberikan penampilan yang modern dan bersih, cocok untuk menambah estetika bangunan baik rumah tinggal maupun bangunan komersial. Jendela fixed UPVC juga memiliki sifat isolasi yang baik, membantu mempertahankan suhu ruangan dan mengurangi kebisingan dari luar. Produk ini memerlukan sedikit perawatan dan umumnya dipilih untuk area-area di mana ventilasi udara tidak menjadi kebutuhan utama.', 'Rp. 600.000', '60cm x 120cm', array['/images/products/jendela-fixed-1.png', '/images/products/jendela-fixed-2.png', '/images/products/jendela-fixed-3.png']::text[], 2);
  insert into public.products (category_slug, name, description, price, price_size, images, sort_order) values ('jendela-upvc', 'Jendela Swing UPVC', 'Jendela swing UPVC adalah produk yang menggunakan bahan UPVC (Unplasticized Polyvinyl Chloride) yang berkualitas tinggi. Desainnya memungkinkan jendela untuk dibuka dengan cara berayun (swing) ke dalam atau ke luar ruangan. Jendela ini menawarkan kombinasi antara kekuatan, keamanan, dan estetika yang modern. Material UPVC membuatnya tahan terhadap cuaca ekstrem dan membutuhkan sedikit perawatan. Dengan kemampuan isolasi yang baik, jendela swing UPVC membantu mempertahankan suhu ruangan dan mengurangi kebisingan dari luar. Cocok digunakan untuk rumah tinggal maupun bangunan komersial sebagai pilihan yang praktis dan efisien dalam memaksimalkan pencahayaan dan ventilasi udara.', 'Rp. 1.176.000', '60cm x 120cm', array['/images/products/jendela-swing-1.png', '/images/products/jendela-swing-2.png', '/images/products/jendela-swing-3.png']::text[], 3);
